from functools import total_ordering


@total_ordering
class LogEntry(object):
    """ Top-level base class for log entries

        Provides method to provide timestamp of a LogEntry

    """

    def __init__(self, timestamp, **kwargs):
        """
        Provide a LogEntry

        :param datetime.datetime timestamp: timestamp of log entry
        """
        super(LogEntry, self).__init__(**kwargs)
        self.__timestamp = timestamp

    @property
    def timestamp(self):
        """
        Provide timestamp of a LogEntry

        :return: timestamp of log entry
        :rtype: datetime.datetime


        """
        return self.__timestamp

    def __eq__(self, other):
        """Compare LogEntry objects

        :param other: Another log entry object

        :return: True if two object's attributes are equal else false
        """
        if self is other:
            return True
        elif not isinstance(other, LogEntry):
            return False
        else:
            return self.__timestamp == other.__timestamp

    def __lt__(self, other):
        """

        :param other: Another log entry object
        :return: Returns true if another log entry object is greater
        """
        return self.__timestamp < other.__timestamp
